package edgefleet

import (
	"bytes"
	"errors"
	"fmt"
	"io"
	"strings"
	"testing"
)

// This file pins the distinction between a clean end of input and a reader
// failure mid-record. At clean EOF the last unterminated (but otherwise
// complete) line is still a record; after a non-EOF read error only lines
// whose newline has already been received are records, even when the line and
// the error came back from the same Read. The unread-looking tail must never
// become an event, watermark or idle declaration, and so can never produce a
// late notice or a window result; the caller gets the reader's own error
// through errors.Is.

// collectedLine is one line handed to the readAggregateLines callback.
type collectedLine struct {
	text string
	no   int
}

func collectLines(t *testing.T, r io.Reader) ([]collectedLine, error) {
	t.Helper()
	var got []collectedLine
	err := readAggregateLines(r, func(line string, lineNo int) error {
		got = append(got, collectedLine{text: line, no: lineNo})
		return nil
	})
	return got, err
}

// TestReadAggregateLinesEOFVsReadError checks the primitive directly: clean
// EOF delivers one final unterminated line; a non-EOF error never does.
func TestReadAggregateLinesEOFVsReadError(t *testing.T) {
	t.Run("clean EOF keeps unterminated final line", func(t *testing.T) {
		got, err := collectLines(t, strings.NewReader("a\nb\r\nc"))
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		want := []collectedLine{{"a", 1}, {"b", 2}, {"c", 3}}
		if fmt.Sprint(got) != fmt.Sprint(want) {
			t.Fatalf("lines = %v, want %v (CR stripped, final line kept)", got, want)
		}
	})
	t.Run("EOF exactly on a newline adds no blank line", func(t *testing.T) {
		got, err := collectLines(t, strings.NewReader("a\n"))
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		want := []collectedLine{{"a", 1}}
		if fmt.Sprint(got) != fmt.Sprint(want) {
			t.Fatalf("lines = %v, want %v", got, want)
		}
	})
	t.Run("blank physical lines count", func(t *testing.T) {
		got, err := collectLines(t, strings.NewReader("\n\nthird\n"))
		if err != nil {
			t.Fatalf("unexpected error: %v", err)
		}
		want := []collectedLine{{"", 1}, {"", 2}, {"third", 3}}
		if fmt.Sprint(got) != fmt.Sprint(want) {
			t.Fatalf("lines = %v, want %v", got, want)
		}
	})
	t.Run("read error drops the unterminated tail", func(t *testing.T) {
		input := "first\nsecond\ntail-without-newline"
		failAt := len("first\nsecond\n") + len("tail-without-newline")
		got, err := collectLines(t, &failingAfterReader{
			data: []byte(input), failAt: failAt, err: errSentinelChunkedRead,
		})
		if !errors.Is(err, errSentinelChunkedRead) {
			t.Fatalf("error = %v, want the reader's original error via errors.Is", err)
		}
		want := []collectedLine{{"first", 1}, {"second", 2}}
		if fmt.Sprint(got) != fmt.Sprint(want) {
			t.Fatalf("lines = %v, want only newline-terminated lines %v", got, want)
		}
	})
	t.Run("error with bytes still completes co-delivered lines", func(t *testing.T) {
		// One Read hands back a complete line, an unterminated tail and the
		// error together. Only the complete line is delivered.
		input := "first\ndangling"
		got, err := collectLines(t, &failingAfterReader{
			data: []byte(input), failAt: len(input),
			err: errSentinelChunkedRead, errOnBoundary: true,
		})
		if !errors.Is(err, errSentinelChunkedRead) {
			t.Fatalf("error = %v, want reader error", err)
		}
		want := []collectedLine{{"first", 1}}
		if fmt.Sprint(got) != fmt.Sprint(want) {
			t.Fatalf("lines = %v, want %v", got, want)
		}
	})
	t.Run("callback error wins over a co-arriving read error", func(t *testing.T) {
		stop := errors.New("callback stop")
		var delivered int
		r := &failingAfterReader{
			data:   []byte("first\nrest"),
			failAt: len("first\nrest"),
			err:    errSentinelChunkedRead, errOnBoundary: true,
		}
		err := readAggregateLines(r, func(string, int) error {
			delivered++
			return stop
		})
		if !errors.Is(err, stop) {
			t.Fatalf("error = %v, want callback error to take precedence", err)
		}
		if delivered != 1 {
			t.Fatalf("callback ran %d times, want 1", delivered)
		}
	})
	t.Run("tail is dropped byte by byte too", func(t *testing.T) {
		input := "first\nsecond\ndangling"
		failAt := len(input)
		got, err := collectLines(t, &failingAfterReader{
			data: []byte(input), failAt: failAt,
			err: errSentinelChunkedRead, chunk: 1, errOnBoundary: true,
		})
		if !errors.Is(err, errSentinelChunkedRead) {
			t.Fatalf("error = %v, want reader error", err)
		}
		want := []collectedLine{{"first", 1}, {"second", 2}}
		if fmt.Sprint(got) != fmt.Sprint(want) {
			t.Fatalf("lines = %v, want %v", got, want)
		}
	})
}

// combinedEOFFailure is a combined error whose chain contains io.EOF
// alongside a distinct failure cause, as some readers (multiplexed streams,
// wrapped connections) report when an upstream failure coincides with the
// local end. errors.Is matches both, but it is not a clean end.
type combinedEOFFailure struct {
	cause error
}

func (e *combinedEOFFailure) Error() string { return "read failure at end: " + e.cause.Error() }
func (e *combinedEOFFailure) Unwrap() []error {
	return []error{io.EOF, e.cause}
}

// wrappedEOF is io.EOF carried in a fmt %w wrapper.
func wrappedEOF() error { return fmt.Errorf("connection reset at end: %w", io.EOF) }

// TestReadAggregateLinesBareEOFOnly: the end-of-input rule must accept only
// the bare io.EOF sentinel. A wrapped io.EOF and a combined error containing
// io.EOF are read failures: the unterminated tail is dropped and the reader's
// own error is returned with its chain intact.
func TestReadAggregateLinesBareEOFOnly(t *testing.T) {
	t.Run("wrapped io.EOF is a failure and drops the tail", func(t *testing.T) {
		input := "first\nsecond\ntail-without-newline"
		readErr := wrappedEOF()
		got, err := collectLines(t, &failingAfterReader{
			data: []byte(input), failAt: len(input),
			err: readErr, errOnBoundary: true,
		})
		if err != readErr {
			t.Fatalf("error = %v, want the reader's original error unchanged", err)
		}
		if !errors.Is(err, io.EOF) {
			t.Fatalf("wrapped error must stay reachable via errors.Is: %v", err)
		}
		want := []collectedLine{{"first", 1}, {"second", 2}}
		if fmt.Sprint(got) != fmt.Sprint(want) {
			t.Fatalf("lines = %v, want only newline-terminated lines %v", got, want)
		}
	})
	t.Run("combined error containing io.EOF is a failure and drops the tail", func(t *testing.T) {
		input := "first\nsecond\ntail-without-newline"
		readErr := &combinedEOFFailure{cause: errSentinelChunkedRead}
		got, err := collectLines(t, &failingAfterReader{
			data: []byte(input), failAt: len(input),
			err: readErr, errOnBoundary: true,
		})
		if err != readErr {
			t.Fatalf("error = %v, want the reader's original combined error unchanged", err)
		}
		if !errors.Is(err, io.EOF) {
			t.Fatalf("errors.Is must still follow the chain to io.EOF: %v", err)
		}
		if !errors.Is(err, errSentinelChunkedRead) {
			t.Fatalf("errors.Is must reach the actual failure cause: %v", err)
		}
		want := []collectedLine{{"first", 1}, {"second", 2}}
		if fmt.Sprint(got) != fmt.Sprint(want) {
			t.Fatalf("lines = %v, want only newline-terminated lines %v", got, want)
		}
	})
	t.Run("combined error still completes co-delivered newline lines", func(t *testing.T) {
		input := strings.Join([]string{
			`{"type":"event","key":"k","time":100,"value":2}`,
			`{"type":"watermark","time":1000}`,
			`{"type":"event","key":"k","time":900,"value":3}`, // unterminated tail
		}, "\n")
		readErr := &combinedEOFFailure{cause: errSentinelChunkedRead}
		var out, late bytes.Buffer
		err := RunAggregate(&failingAfterReader{
			data: []byte(input), failAt: len(input),
			err: readErr, errOnBoundary: true,
		}, 1000, &out, &late)
		if err != readErr {
			t.Fatalf("error = %v, want the combined read error unchanged", err)
		}
		wantWindow := `{"key":"k","start":0,"end":1000,"count":1,"sum":2}` + "\n"
		if out.String() != wantWindow {
			t.Fatalf("the newline-terminated watermark must close the window first:\n got: %q\nwant: %q", out.String(), wantWindow)
		}
		if late.String() != "" {
			t.Fatalf("unterminated tail must not produce late notices: %q", late.String())
		}
	})
}

// TestReadAggregateCombinedEOFScenario is the exact scenario from the fix
// report: length-1000 window, a newline-terminated event key=k time=100
// value=2, then a time=1000 watermark without a newline. A combined error
// carrying io.EOF and a read failure must fail without emitting [0,1000) and
// without reporting the tail as a JSON error. The same bytes at a real clean
// EOF must still produce count 1, sum 2.
func TestReadAggregateCombinedEOFScenario(t *testing.T) {
	event := `{"type":"event","key":"k","time":100,"value":2}` + "\n"
	watermark := `{"type":"watermark","time":1000}`

	t.Run("combined EOF failure emits nothing", func(t *testing.T) {
		for _, tail := range []string{
			watermark,                          // complete-looking JSON, no newline
			`{"type":"watermark","time":1000`,  // truncated
			`{`,                                // obviously damaged
		} {
			tail := tail
			t.Run("", func(t *testing.T) {
				input := event + tail
				readErr := &combinedEOFFailure{cause: errSentinelChunkedRead}
				var out, late bytes.Buffer
				err := RunAggregate(&failingAfterReader{
					data: []byte(input), failAt: len(input),
					err: readErr, errOnBoundary: true,
				}, 1000, &out, &late)
				if err != readErr {
					t.Fatalf("error = %v, want the combined read error unchanged", err)
				}
				if !errors.Is(err, errSentinelChunkedRead) {
					t.Fatalf("errors.Is must find the read failure cause: %v", err)
				}
				if _, ok := err.(*InputError); ok {
					t.Fatalf("the tail must not be reported as a JSON error: %v", err)
				}
				if out.String() != "" {
					t.Fatalf("no window may close on the unterminated watermark: %q", out.String())
				}
				if late.String() != "" {
					t.Fatalf("no late notices allowed: %q", late.String())
				}
			})
		}
	})
	t.Run("wrapped EOF failure emits nothing", func(t *testing.T) {
		input := event + watermark
		readErr := wrappedEOF()
		var out, late bytes.Buffer
		err := RunAggregate(&failingAfterReader{
			data: []byte(input), failAt: len(input),
			err: readErr, errOnBoundary: true,
		}, 1000, &out, &late)
		if err != readErr {
			t.Fatalf("error = %v, want the wrapped error unchanged", err)
		}
		if _, ok := err.(*InputError); ok {
			t.Fatalf("wrapped EOF is a read failure, not an input error: %v", err)
		}
		if out.String() != "" {
			t.Fatalf("wrapped EOF must not close the window: %q", out.String())
		}
	})
	t.Run("same bytes at bare io.EOF produce count 1 sum 2", func(t *testing.T) {
		input := event + watermark
		var out, late bytes.Buffer
		if err := RunAggregate(strings.NewReader(input), 1000, &out, &late); err != nil {
			t.Fatalf("clean EOF must succeed: %v", err)
		}
		want := `{"key":"k","start":0,"end":1000,"count":1,"sum":2}` + "\n"
		if out.String() != want {
			t.Fatalf("clean EOF output:\n got: %q\nwant: %q", out.String(), want)
		}
		if late.String() != "" {
			t.Fatalf("unexpected late notices: %q", late.String())
		}
	})
}

// TestReadAggregateErrorUnterminatedTailIsNotARecord drives the exact scenario
// from the fix: length-1000 windows, event key=k time=100 value=2 with a
// newline, then a time=1000 watermark JSON without a newline, and the reader
// fails. The watermark must not close [0,1000); a malformed tail must not be
// reported as an input error either -- the read failure is what surfaces.
func TestReadAggregateErrorUnterminatedTailIsNotARecord(t *testing.T) {
	event := `{"type":"event","key":"k","time":100,"value":2}` + "\n"
	watermark := `{"type":"watermark","time":1000}`

	cases := []struct {
		name string
		tail string
	}{
		{"complete-looking watermark tail", watermark},
		{"truncated watermark tail", `{"type":"watermark","time":1000`},
		{"garbage tail", `{"type":wate`},
	}
	deliveries := []struct {
		name           string
		errOnBoundary  bool
		chunk          int
		errorAfterTail bool
	}{
		{"error on the next read", false, 0, true},
		{"tail bytes and error in one read", true, 1 << 20, false},
		{"one byte per read, error with last byte", true, 1, false},
	}
	for _, tc := range cases {
		for _, dl := range deliveries {
			name := tc.name + "/" + dl.name
			t.Run(name, func(t *testing.T) {
				input := event + tc.tail
				var r io.Reader
				if dl.errorAfterTail {
					// The read carrying the tail succeeds; the following read fails.
					r = &failingAfterReader{data: []byte(input), failAt: len(input), err: errSentinelChunkedRead}
				} else {
					r = &failingAfterReader{data: []byte(input), failAt: len(input), err: errSentinelChunkedRead, errOnBoundary: dl.errOnBoundary, chunk: dl.chunk}
				}
				var out, late bytes.Buffer
				err := RunAggregate(r, 1000, &out, &late)
				if !errors.Is(err, errSentinelChunkedRead) {
					t.Fatalf("error = %T %v, want the reader's original error via errors.Is", err, err)
				}
				if _, ok := err.(*InputError); ok {
					t.Fatalf("read failure must not be masked by a JSON/input error: %v", err)
				}
				if out.String() != "" {
					t.Fatalf("unterminated watermark must not close a window, stdout = %q", out.String())
				}
				if late.String() != "" {
					t.Fatalf("unterminated tail must not produce late notices: %q", late.String())
				}
			})
		}
	}
}

// TestReadAggregateErrorTerminatedRecordSameReadStillProcessed: when the
// failing Read also delivers the watermark's newline, the window must be
// emitted first, in order, and only then does the run fail with the read
// error.
func TestReadAggregateErrorTerminatedRecordSameReadStillProcessed(t *testing.T) {
	input := strings.Join([]string{
		`{"type":"event","key":"k","time":100,"value":2}`,
		`{"type":"watermark","time":1000}`,
		``,
	}, "\n") // ends with the watermark's newline
	wantWindow := `{"key":"k","start":0,"end":1000,"count":1,"sum":2}` + "\n"

	check := func(t *testing.T, r io.Reader) {
		var out, late bytes.Buffer
		err := RunAggregate(r, 1000, &out, &late)
		if !errors.Is(err, errSentinelChunkedRead) {
			t.Fatalf("error = %v, want reader error after processing complete lines", err)
		}
		if out.String() != wantWindow {
			t.Fatalf("window closed by the newline-terminated watermark must be emitted:\n got: %q\nwant: %q", out.String(), wantWindow)
		}
		if late.String() != "" {
			t.Fatalf("unexpected late notices: %q", late.String())
		}
	}

	t.Run("newline and error in the same read", func(t *testing.T) {
		check(t, &failingAfterReader{
			data: []byte(input), failAt: len(input),
			err: errSentinelChunkedRead, errOnBoundary: true,
		})
	})
	t.Run("one byte per read, last byte with error", func(t *testing.T) {
		check(t, &failingAfterReader{
			data: []byte(input), failAt: len(input),
			err: errSentinelChunkedRead, errOnBoundary: true, chunk: 1,
		})
	})
}

// TestReadAggregateErrorUnterminatedLateEventMakesNoNoise: a tail event that
// the current watermark would judge late must not produce a late-event notice
// when the read fails before its newline arrives.
func TestReadAggregateErrorUnterminatedLateEventMakesNoNoise(t *testing.T) {
	input := strings.Join([]string{
		`{"type":"watermark","time":500}`, // line 1 complete
		`{"type":"event","key":"k","time":100,"value":2}`,
	}, "\n") // line 2 unterminated
	var out, late bytes.Buffer
	err := RunAggregate(&failingAfterReader{
		data: []byte(input), failAt: len(input),
		err: errSentinelChunkedRead, errOnBoundary: true,
	}, 1000, &out, &late)
	if !errors.Is(err, errSentinelChunkedRead) {
		t.Fatalf("error = %v, want reader error", err)
	}
	if late.String() != "" {
		t.Fatalf("unterminated late event must not yield a late notice: %q", late.String())
	}
	if out.String() != "" {
		t.Fatalf("no window results possible, got %q", out.String())
	}
}

// TestReadAggregateErrorUnterminatedIdleDoesNotCloseWindows: an idle
// declaration whose newline never arrives must not move the partitioned
// effective watermark or close anything.
func TestReadAggregateErrorUnterminatedIdleDoesNotCloseWindows(t *testing.T) {
	input := strings.Join([]string{
		`{"type":"event","key":"k","time":100,"value":2,"partition":0}`,
		`{"type":"watermark","time":1000,"partition":0}`,
		`{"type":"idle","partition":1}`, // would make the effective watermark 1000
	}, "\n")
	var out, late bytes.Buffer
	err := RunAggregatePartitionedSliding(&failingAfterReader{
		data: []byte(input), failAt: len(input),
		err: errSentinelChunkedRead, errOnBoundary: true,
	}, 1000, 1000, 2, &out, &late)
	if !errors.Is(err, errSentinelChunkedRead) {
		t.Fatalf("error = %v, want reader error", err)
	}
	if out.String() != "" {
		t.Fatalf("unterminated idle declaration must not close [0,1000): %q", out.String())
	}

	// Control: the same idle record WITH a newline delivered together with
	// the read error closes the window before the failure surfaces.
	terminated := input + "\n"
	var out2, late2 bytes.Buffer
	err2 := RunAggregatePartitionedSliding(&failingAfterReader{
		data: []byte(terminated), failAt: len(terminated),
		err: errSentinelChunkedRead, errOnBoundary: true,
	}, 1000, 1000, 2, &out2, &late2)
	if !errors.Is(err2, errSentinelChunkedRead) {
		t.Fatalf("control error = %v, want reader error", err2)
	}
	want := `{"key":"k","start":0,"end":1000,"count":1,"sum":2}` + "\n"
	if out2.String() != want {
		t.Fatalf("newline-terminated idle record must close the window first:\n got: %q\nwant: %q", out2.String(), want)
	}
}

// TestReadAggregateErrorEarlierRecordOrOutputFailureKept: a record error or an
// output write error on a complete line delivered by the same Read that
// carries the read failure must remain the reported failure; the read error,
// learned only afterwards, must not overwrite it.
func TestReadAggregateErrorEarlierRecordOrOutputFailureKept(t *testing.T) {
	t.Run("record error on a complete line wins", func(t *testing.T) {
		input := `{"type":"bogus"}` + "\n" + `{"type":"watermark","time":1000}`
		var out, late bytes.Buffer
		err := RunAggregate(&failingAfterReader{
			data: []byte(input), failAt: len(input),
			err: errSentinelChunkedRead, errOnBoundary: true,
		}, 1000, &out, &late)
		var ie *InputError
		if !errors.As(err, &ie) || ie.Line != 1 {
			t.Fatalf("error = %v, want *InputError on physical line 1", err)
		}
		if errors.Is(err, errSentinelChunkedRead) {
			t.Fatalf("the record error must replace the later read error: %v", err)
		}
	})
	t.Run("output write error on a complete line wins", func(t *testing.T) {
		input := strings.Join([]string{
			`{"type":"event","key":"k","time":100,"value":2}`,
			`{"type":"watermark","time":1000}`,
			`{"type":"event","key":"k","time":900,"value":3}`, // unterminated tail
		}, "\n")
		var late bytes.Buffer
		err := RunAggregate(&failingAfterReader{
			data: []byte(input), failAt: len(input),
			err: errSentinelChunkedRead, errOnBoundary: true,
		}, 1000, &errOnlyWriter{err: errSentinelOutput}, &late)
		var oe *OutputError
		if !errors.As(err, &oe) {
			t.Fatalf("error = %v, want *OutputError", err)
		}
		if !errors.Is(err, errSentinelOutput) {
			t.Fatalf("errors.Is must reach the writer error: %v", err)
		}
		if errors.Is(err, errSentinelChunkedRead) {
			t.Fatalf("the output error must replace the read error learned after it: %v", err)
		}
	})
}

// TestReadAggregateCleanEOFContractStillHolds summarizes the behavior that had
// to stay byte-identical through the reader rewrite: a valid final record
// without a trailing newline processes at clean EOF, while a damaged final
// record is an input error carrying its physical line number.
func TestReadAggregateCleanEOFContractStillHolds(t *testing.T) {
	t.Run("valid unterminated final record processes", func(t *testing.T) {
		input := `{"type":"event","key":"k","time":100,"value":2}` + "\n" +
			`{"type":"watermark","time":1000}`
		var out, late bytes.Buffer
		if err := RunAggregate(strings.NewReader(input), 1000, &out, &late); err != nil {
			t.Fatalf("clean EOF: %v", err)
		}
		want := `{"key":"k","start":0,"end":1000,"count":1,"sum":2}` + "\n"
		if out.String() != want {
			t.Fatalf("got %q, want %q", out.String(), want)
		}
	})
	t.Run("damaged unterminated final record is a line-numbered input error", func(t *testing.T) {
		input := `{"type":"event","key":"k","time":100,"value":2}` + "\n" +
			`{"type":"watermark","time":1000`
		var out, late bytes.Buffer
		err := RunAggregate(strings.NewReader(input), 1000, &out, &late)
		var ie *InputError
		if !errors.As(err, &ie) || ie.Line != 2 {
			t.Fatalf("error = %v, want *InputError on physical line 2", err)
		}
		if !strings.Contains(ie.Reason, "invalid JSON") {
			t.Fatalf("reason = %q, want invalid JSON", ie.Reason)
		}
		if out.String() != "" {
			t.Fatalf("nothing may be emitted: %q", out.String())
		}
	})
}

// Command edgefleet is the 验证者与边缘节点机群管理平台 entry point.
package main

import (
	"errors"
	"flag"
	"fmt"
	"os"

	"github.com/asdhoaiqqq/edgefleet-validator/edgefleet"
)

func main() {
	command := "demo"
	if len(os.Args) > 1 {
		command = os.Args[1]
	}
	switch command {
	case "demo":
		runDemo()
	case "version":
		fmt.Println("edgefleet 0.1.0")
	case "aggregate":
		os.Exit(runAggregate(os.Args[2:]))
	case "help", "-h", "--help":
		usage()
	default:
		fmt.Fprintf(os.Stderr, "unknown command %q\n", command)
		usage()
		os.Exit(2)
	}
}

func usage() {
	fmt.Println("usage: edgefleet [demo|version|aggregate --window-ms <milliseconds> [--slide-ms <milliseconds>] [--partitions <count>]|help]")
	fmt.Println()
	fmt.Println("commands:")
	fmt.Println("  demo       run a built-in fleet health demonstration")
	fmt.Println("  version    print the edgefleet version")
	fmt.Println("  aggregate  aggregate JSON events from standard input into fixed or sliding windows")
	fmt.Println("  help       show this help")
	fmt.Println()
	fmt.Println("aggregate:")
	fmt.Println("  edgefleet aggregate --window-ms <milliseconds> [--slide-ms <milliseconds>] [--partitions <count>]")
	fmt.Println()
	fmt.Println("  --window-ms is a required positive signed 64-bit integer. Aggregation runs")
	fmt.Println("  fully offline and never uses the current time; all timing comes from input.")
	fmt.Println()
	fmt.Println("  standard input is line-delimited JSON with two record types:")
	fmt.Println(`    {"type":"event","key":"sensor-a","time":1200,"value":5}`)
	fmt.Println(`    {"type":"watermark","time":2000}`)
	fmt.Println("  time is a non-negative signed 64-bit millisecond timestamp, value is a")
	fmt.Println("  signed 64-bit integer, and key is a non-empty string. Blank lines are")
	fmt.Println("  ignored, but error line numbers count every physical input line.")
	fmt.Println()
	fmt.Println("  windows start at time zero, have the fixed length given by --window-ms")
	fmt.Println("  and are left-closed, right-open: [start,end). Every valid event for a key")
	fmt.Println("  in a window contributes to its count and sum; windows with no events do")
	fmt.Println("  not produce output. Records may arrive out of order; window membership")
	fmt.Println("  uses event time only.")
	fmt.Println()
	fmt.Println("  --slide-ms makes the windows overlap: it gives the positive signed")
	fmt.Println("  64-bit integer distance between consecutive window starts (0, one")
	fmt.Println("  interval, two intervals, ...), must not exceed --window-ms and does not")
	fmt.Println("  have to divide it. Each valid event counts once in every window that")
	fmt.Println("  contains its event time, adding its value in full to each of them; for")
	fmt.Println("  example length 1000 with interval 600 produces [0,1000), [600,1600),")
	fmt.Println("  [1200,2200), ... and an event at time 1000 is outside the first. When")
	fmt.Println("  --slide-ms is omitted or equals --window-ms the behavior is identical")
	fmt.Println("  to fixed windows.")
	fmt.Println()
	fmt.Println("  a watermark declares that events with time below it are late. Before the")
	fmt.Println("  first watermark every valid event is accepted. After a watermark, every")
	fmt.Println("  window whose end is less than or equal to the watermark is closed once")
	fmt.Println("  and emitted as one JSON line with key,start,end,count,sum; the sum is a")
	fmt.Println("  signed 64-bit integer. Closures are ordered by end ascending and then by")
	fmt.Println("  key in UTF-8 byte order. Watermarks may jump or repeat, and an event at")
	fmt.Println("  exactly the current watermark is still valid; events below the current")
	fmt.Println("  watermark are skipped with a note on standard error, even when they")
	fmt.Println("  would still fall inside an unclosed overlapping window. Still-open")
	fmt.Println("  windows are never emitted at end of input.")
	fmt.Println()
	fmt.Println("  --partitions merges several independent input sources of the same stream.")
	fmt.Println("  <count> must be a positive signed 64-bit integer. When it is given, every")
	fmt.Println("  event and watermark record must additionally carry an integer partition in")
	fmt.Println("  [0,count):")
	fmt.Println(`    {"type":"event","key":"sensor-a","time":1200,"value":5,"partition":0}`)
	fmt.Println(`    {"type":"watermark","time":2000,"partition":0}`)
	fmt.Println(`    {"type":"idle","partition":0}`)
	fmt.Println("  each partition advances its own watermark independently. No effective")
	fmt.Println("  watermark exists until every partition has reported at least once;")
	fmt.Println("  afterwards the effective watermark is the minimum of the per-partition")
	fmt.Println("  values, and window closure and late-event checks use that minimum, so one")
	fmt.Println("  partition's larger watermark can never close a window or drop an event")
	fmt.Println("  ahead of the others. A partition watermark may repeat or jump forward but")
	fmt.Println("  never move backwards. Events from different partitions for the same key")
	fmt.Println("  and window merge into one count and sum; output records never include a")
	fmt.Println("  partition field. Sliding windows combine with partitions: the same key")
	fmt.Println("  from different partitions merges within each overlapping window, and the")
	fmt.Println("  effective watermark alone drives late-event checks and closure. Without")
	fmt.Println("  --partitions the command keeps the single watermark behavior and ignores")
	fmt.Println("  extra fields.")
	fmt.Println()
	fmt.Println("  an idle record declares a partition temporarily without data. It is")
	fmt.Println("  declared by the input only and is never inferred from the current time")
	fmt.Println("  or read gaps. From that record on the partition is excluded from the")
	fmt.Println("  effective watermark, so it no longer holds the others back; the idle")
	fmt.Println("  record itself may close windows. A non-idle partition that has not")
	fmt.Println("  reported yet still keeps the effective watermark unknown; when every")
	fmt.Println("  partition is idle the last produced effective watermark is retained")
	fmt.Println("  (and stays unknown if none was produced). Idleness is not an infinite")
	fmt.Println("  watermark and does not drop pending events. Repeating an idle record")
	fmt.Println("  for the same partition succeeds without extra output. A partition")
	fmt.Println("  resumes on its next watermark record: its time must be at least both")
	fmt.Println("  its own previous watermark and the current effective watermark. An")
	fmt.Println("  event arriving while the partition is idle is fatal; it neither")
	fmt.Println("  resumes the partition nor is silently treated as late. In single")
	fmt.Println("  watermark mode an idle record is an unknown record type.")
	fmt.Println()
	fmt.Println("  invalid command parameters -- a missing --window-ms, or a")
	fmt.Println("  non-positive --window-ms or --slide-ms, or a --slide-ms larger than")
	fmt.Println("  --window-ms, or a non-positive --partitions -- print the reason to")
	fmt.Println("  standard error and exit non-zero before any input is read. Malformed")
	fmt.Println("  JSON, missing or mistyped fields, out-of-range integers, unknown")
	fmt.Println("  record types, missing or out-of-range partitions, partition watermark")
	fmt.Println("  regression, an event for an idle partition, a resume watermark below")
	fmt.Println("  the partition's previous or the effective watermark, an event key")
	fmt.Println("  whose character encoding or Unicode escape is damaged (invalid UTF-8")
	fmt.Println("  bytes, or an unpaired or mispaired surrogate), and window-end,")
	fmt.Println("  event-count or cumulative-sum overflow print the input line number and")
	fmt.Println("  reason to standard error and stop processing with a non-zero exit; no")
	fmt.Println("  further records are read and earlier output is retained. A window")
	fmt.Println("  result or late-event notice that cannot be written in full (the")
	fmt.Println("  output writer errors, even after accepting a prefix, or accepts too")
	fmt.Println("  few bytes without an error) is likewise fatal with the triggering")
	fmt.Println("  input line number, the affected key and window or the skipped event")
	fmt.Println("  time and watermark, and the writer's error; the failed content is not")
	fmt.Println("  resent, no further windows are emitted and content already written is")
	fmt.Println("  retained. Standard output contains window results only. A failure while")
	fmt.Println("  reading standard input is likewise fatal: records whose newline was")
	fmt.Println("  received, including those carried by the failing read, are processed in")
	fmt.Println("  order first, but the unterminated trailing bytes never become a record,")
	fmt.Println("  and the reader's error is reported here with a non-zero exit; clean end")
	fmt.Println("  of input is not a read failure, so a final record without a trailing")
	fmt.Println("  newline is still processed.")
}

func runAggregate(args []string) int {
	fs := flag.NewFlagSet("aggregate", flag.ContinueOnError)
	fs.SetOutput(os.Stderr)
	fs.Usage = func() {
		fmt.Fprintln(fs.Output(), "usage: edgefleet aggregate --window-ms <milliseconds> [--slide-ms <milliseconds>] [--partitions <count>]")
		fmt.Fprintln(fs.Output(), `run "edgefleet help" for the full record and window closure rules`)
	}
	windowMillis := fs.Int64("window-ms", 0, "window length in milliseconds (required, positive signed 64-bit integer)")
	slideMillis := fs.Int64("slide-ms", 0, "distance between consecutive window starts in milliseconds (optional positive signed 64-bit integer, no greater than --window-ms); defaults to the window length for non-overlapping fixed windows")
	partitions := fs.Int64("partitions", 0, "number of input partitions (optional positive signed 64-bit integer); when set, every record must carry an integer partition in [0,count)")
	if err := fs.Parse(args); err != nil {
		return 2
	}
	if fs.NArg() != 0 {
		fmt.Fprintf(os.Stderr, "aggregate accepts no positional arguments, got %v\n", fs.Args())
		fs.Usage()
		return 2
	}
	windowSpecified := false
	slideSpecified := false
	partitionsSpecified := false
	fs.Visit(func(f *flag.Flag) {
		switch f.Name {
		case "window-ms":
			windowSpecified = true
		case "slide-ms":
			slideSpecified = true
		case "partitions":
			partitionsSpecified = true
		}
	})
	if !windowSpecified {
		fmt.Fprintln(os.Stderr, "aggregate requires --window-ms <milliseconds>")
		fs.Usage()
		return 2
	}
	// An omitted --slide-ms defaults to the window length (fixed windows).
	// This is an omission policy specific to the command: an explicitly given
	// zero is left untouched, so it is still rejected below rather than being
	// silently treated as the default.
	if !slideSpecified {
		*slideMillis = *windowMillis
	}
	// The numeric limits are shared with the library entry points and live in
	// edgefleet.ValidateAggregateParams; only the flag-named wording and exit
	// code are command-specific. The shared report order (window, slide,
	// slide-vs-window, partitions) is the order this command already used.
	if err := edgefleet.ValidateAggregateParams(*windowMillis, *slideMillis, *partitions); err != nil {
		var paramErr *edgefleet.AggregateParamError
		if errors.As(err, &paramErr) {
			fmt.Fprint(os.Stderr, aggregateParamCLIError(paramErr))
		} else {
			fmt.Fprintln(os.Stderr, "aggregate:", err)
		}
		return 2
	}
	// The command rejects an explicitly supplied non-positive --partitions;
	// the library accepts zero as its legacy single-watermark mode selector.
	// The shared validator already rejected negative counts, so here this only
	// catches an explicit zero, kept as the command's own policy.
	if partitionsSpecified && *partitions <= 0 {
		fmt.Fprintf(os.Stderr, "aggregate --partitions must be a positive signed 64-bit integer, got %d\n", *partitions)
		return 2
	}
	var err error
	if partitionsSpecified {
		err = edgefleet.RunAggregatePartitionedSliding(os.Stdin, *windowMillis, *slideMillis, *partitions, os.Stdout, os.Stderr)
	} else {
		err = edgefleet.RunAggregateSliding(os.Stdin, *windowMillis, *slideMillis, os.Stdout, os.Stderr)
	}
	if err != nil {
		fmt.Fprintln(os.Stderr, "aggregate:", err)
		return 1
	}
	return 0
}

// aggregateParamCLIError renders a shared *edgefleet.AggregateParamError in
// the command's existing flag-named wording. The limit and its checking order
// come from edgefleet.ValidateAggregateParams; only this text and the exit
// code are command-specific.
func aggregateParamCLIError(e *edgefleet.AggregateParamError) string {
	switch e.Kind {
	case edgefleet.AggregateParamTooLarge:
		return fmt.Sprintf("aggregate --slide-ms %d must not exceed --window-ms %d\n", e.Value, e.Limit)
	case edgefleet.AggregateParamNotPositive:
		switch e.Field {
		case edgefleet.AggregateParamWindow:
			return fmt.Sprintf("aggregate --window-ms must be a positive signed 64-bit integer, got %d\n", e.Value)
		case edgefleet.AggregateParamSlide:
			return fmt.Sprintf("aggregate --slide-ms must be a positive signed 64-bit integer, got %d\n", e.Value)
		case edgefleet.AggregateParamPartitions:
			return fmt.Sprintf("aggregate --partitions must be a positive signed 64-bit integer, got %d\n", e.Value)
		}
	}
	return fmt.Sprintf("aggregate: invalid %s parameter %d\n", e.Field, e.Value)
}

func runDemo() {
	nodes := []edgefleet.Node{
		{ID: "val-eu-1", Region: "eu", Version: "1.26.0", Online: true},
		{ID: "val-us-1", Region: "us", Version: "1.25.4", Online: true, Missed: 3},
		{ID: "edge-ap-1", Region: "ap", Version: "1.26.0", Online: false},
	}
	unhealthy := 0
	for _, node := range nodes {
		health := edgefleet.Evaluate(node, "1.26.0", 1)
		if !health.Healthy {
			unhealthy++
		}
		fmt.Printf("node=%s healthy=%v findings=%v\n", health.Node, health.Healthy, health.Findings)
	}
	fmt.Println("rollout order:", edgefleet.Plan(nodes, "1.26.0"))
	fmt.Printf("summary: %d of %d nodes need attention\n", unhealthy, len(nodes))
}

