1	package edgefleet
2	
3	import (
4		"bytes"
5		"errors"
6		"fmt"
7		"io"
8		"strings"
9		"testing"
10	)
11	
12	// This file guards the zero-byte-read stall contract of the aggregate input
13	// boundary. A library entry point's reader may legitimately return (0, nil)
14	// while one record is still halfway through: that is neither end of input nor
15	// a read error, and the half-record must survive. Up to 100 consecutive such
16	// reads are tolerated and simply repeated; ANY read delivering bytes (even a
17	// fragment too short to complete a record) resets the consecutive count; the
18	// 101st consecutive zero-byte read ends the run with io.ErrNoProgress.
19	//
20	// Everything observable through that stall must stay byte-identical to an
21	// uninterrupted run: per-partition watermark merging, sliding-window results,
22	// output ordering and the physical line numbers on late notices. Once the
23	// progress limit fails the run, already complete output stays, open windows
24	// are not emitted late, a newline-less tail (even valid JSON) never becomes a record,
25	// and no further read is attempted. All scenarios are scripted in-memory, so
26	// they reproduce offline with no timing dependency.
27	
28	// scriptedStep is one programmed Read behavior. When zero > 0 the next Reads
29	// return (0, nil) that many times first; then data (if any) is handed out
30	// across however many Reads the caller's buffer needs; err is returned alone
31	// as (0, err) once the step is reached, poisoning any Read the aggregate was
32	// not supposed to make.
33	type scriptedStep struct {
34		data []byte
35		zero int
36		err  error
37	}
38	
39	// scriptedReader serves a fixed Read script instead of relying on timing or
40	// goroutines, so stall behavior is deterministic offline.
41	type scriptedReader struct {
42		steps []scriptedStep
43		si    int
44		off   int
45	}
46	
47	func (r *scriptedReader) Read(p []byte) (int, error) {
48		for r.si < len(r.steps) {
49			st := &r.steps[r.si]
50			if st.zero > 0 {
51				st.zero--
52				return 0, nil
53			}
54			if st.err != nil {
55				return 0, st.err
56			}
57			if r.off < len(st.data) {
58				n := copy(p, st.data[r.off:])
59				r.off += n
60				if r.off == len(st.data) {
61					r.si++
62					r.off = 0
63				}
64				return n, nil
65			}
66			r.si++
67			r.off = 0
68		}
69		return 0, io.EOF
70	}
71	
72	func stepData(s string) scriptedStep    { return scriptedStep{data: []byte(s)} }
73	func stepZeroReads(n int) scriptedStep  { return scriptedStep{zero: n} }
74	func stepPoison(err error) scriptedStep { return scriptedStep{err: err} }
75	
76	// fragmentedSteps cuts s into fixed-size byte pieces, inserting shortPause
77	// zero-byte reads after every piece, so every record (and every multibyte key
78	// byte) is delivered split across many Reads with stalls in between. After
79	// the piece containing each offset in longAfterOffsets an extra long pause of
80	// that many zero-byte reads is inserted, landing deliberately in the middle of
81	// a chosen event or watermark record.
82	type longPauseOffset struct {
83		offset int
84		pause  int
85	}
86	
87	func fragmentedSteps(s string, size, shortPause int, longs ...longPauseOffset) []scriptedStep {
88		var steps []scriptedStep
89		for i := 0; i < len(s); i += size {
90			j := i + size
91			if j > len(s) {
92				j = len(s)
93			}
94			steps = append(steps, stepData(s[i:j]))
95			pause := shortPause
96			for _, lp := range longs {
97				if lp.offset >= i && lp.offset < j {
98					pause = lp.pause
99				}
100			}
101			steps = append(steps, stepZeroReads(pause))
102		}
103		return steps
104	}
105	
106	// runScriptedPartitionedSliding runs the length-1000/step-600/two-partition
107	// sliding aggregation over a scripted reader, capturing both outputs.
108	func runScriptedPartitionedSliding(t *testing.T, steps []scriptedStep) (string, string, error) {
109		t.Helper()
110		var out, late bytes.Buffer
111		err := RunAggregatePartitionedSliding(&scriptedReader{steps: steps}, 1000, 600, 2, &out, &late)
112		return out.String(), late.String(), err
113	}
