115	// stallScenarioLines is the reference stream for this file: length 1000ms,
116	// slide 600ms, two active partitions, one key shared across partitions.
117	//
118	//	line 1: partition 0 event 温度 time 700 value 2 -> [0,1000), [600,1600)
119	//	line 2: blank physical line
120	//	line 3: partition 1 event 温度 time 1000 value 3 -> [600,1600) only
121	//	line 4: partition 0 watermark 1600 (effective watermark still unknown)
122	//	line 5: partition 1 watermark 1000 (min 1000; [0,1000) closes)
123	//	line 6: blank physical line
124	//	line 7: partition 1 event time 999 value 9, late vs effective 1000
125	//	line 8: partition 1 watermark 1600 (min 1600; [600,1600) closes)
126	//
127	// Two blank lines are interleaved on purpose: they consume physical line
128	// numbers, while zero-byte reads must not, so the late notice has to name
129	// line 7 through every stall schedule below.
130	func stallScenarioLines() []string {
131		return []string{
132			`{"type":"event","key":"温度","time":700,"value":2,"partition":0}`,
133			``,
134			`{"type":"event","key":"温度","time":1000,"value":3,"partition":1}`,
135			`{"type":"watermark","time":1600,"partition":0}`,
136			`{"type":"watermark","time":1000,"partition":1}`,
137			``,
138			`{"type":"event","key":"温度","time":999,"value":9,"partition":1}`,
139			`{"type":"watermark","time":1600,"partition":1}`,
140		}
141	}
