223			// Two runs of 100 zero-byte reads separated only by a few bytes of an
224			// as-yet incomplete record: 200 zero-byte reads happen in total, but
225			// neither streak reaches 101, so the run completes once the newline
226			// arrives. The limit guards consecutive lack of progress, not a
227			// lifetime total.
228			var got []collectedLine
229			err := readAggregateLines(&scriptedReader{steps: []scriptedStep{
230				stepData("a\n"),
231				stepZeroReads(100),
