249	// TestZeroByteReadMidRecordDoesNotAdvanceWindows drives the full
250	// length-1000/slide-600/two-partition scenario with zero-byte stalls inserted
251	// constantly, including a 100-read pause in the middle of every watermark and
252	// of the late event. Results, ordering and late-notice line number must be
253	// byte-identical to receiving the same stream without stalls: a half-record
254	// pause can neither double-count an event, emit a late notice early, nor close
255	// a window ahead of the record's newline.
256	func TestZeroByteReadMidRecordDoesNotAdvanceWindows(t *testing.T) {
257		lines := stallScenarioLines()
258		var steps []scriptedStep
259		for i, line := range lines {
260			// Include each line and its delimiter; the physical blank lines (2 and
261			// 6) are a bare "\n".
262			chunk := line + "\n"
263			var longs []longPauseOffset
264			if i == 3 || i == 4 || i == 6 { // both watermarks and the late event
265				// Offset 2 lands inside the first 3-byte piece of these records
266				// (`{"t`), i.e. before the record is in any sense complete.
267				longs = append(longs, longPauseOffset{offset: 2, pause: 100})
268			}
269			steps = append(steps, fragmentedSteps(chunk, 3, 5, longs...)...)
270		}
271	
272		out, late, err := runScriptedPartitionedSliding(t, steps)
273		if err != nil {
274			t.Fatalf("stalls between record fragments must not fail the run: %v", err)
275		}
276		if out != stallScenarioWindows {
277			t.Fatalf("window results across stalls:\n got: %q\nwant: %q", out, stallScenarioWindows)
278		}
279		if late != stallScenarioLate {
280			t.Fatalf("late notice across stalls (blank lines count, zero-byte reads do not):\n got: %q\nwant: %q", late, stallScenarioLate)
281		}
