283	
284	// TestZeroByteReadOnePartitionWatermarkCannotCloseThenMinCloses focuses on the
285	// cross-partition merge rule under stalls: with both partitions contributing
286	// events to the same key, one partition reporting a watermark closes nothing,
287	// even when the stream then stalls to the progress limit; a newline-less
288	// watermark for the other partition -- complete-looking JSON sitting in the
289	// buffer through 101 zero-byte reads -- is not processed either, so nothing
290	// closes and the caller gets io.ErrNoProgress rather than a parse error.
291	func TestZeroByteReadOnePartitionWatermarkCannotCloseThenMinCloses(t *testing.T) {
292		throughFirstWatermark := strings.Join([]string{
293			`{"type":"event","key":"温度","time":700,"value":2,"partition":0}`,
294			`{"type":"event","key":"温度","time":1000,"value":3,"partition":1}`,
295			`{"type":"watermark","time":1600,"partition":0}`, // only partition 0
296			``,
297		}, "\n")
298		unterminatedOther := `{"type":"watermark","time":1000,"partition":1}` // valid JSON, no newline
299	
300		out, late, err := runScriptedPartitionedSliding(t, []scriptedStep{
301			stepData(throughFirstWatermark),
302			stepZeroReads(90),
303			stepData(unterminatedOther[:7]), // record fragments while stalled...
304			stepZeroReads(80),               // ...bytes reset the count
305			stepData(unterminatedOther[7:]),
306			stepZeroReads(101), // now the consecutive lack of progress fails
307			stepPoison(errSentinelChunkedRead),
308		})
309		if !errors.Is(err, io.ErrNoProgress) {
310			t.Fatalf("error = %v, want io.ErrNoProgress", err)
311		}
312		if _, ok := err.(*InputError); ok {
313			t.Fatalf("the buffered newline-less tail must not be reported as an input error: %v", err)
314		}
315		if out != "" {
316			t.Fatalf("one partition's watermark and an unterminated watermark must close nothing:\n got: %q", out)
317		}
318		if late != "" {
319			t.Fatalf("no late notices expected, got %q", late)
320		}
321	
322		// Positive control: the same records but the second partition's watermark
323		// gets its newline before the stall -- the min (1000) then closes
324		// [0,1000), and the 100 zero-byte reads that follow are tolerated to a
325		// clean EOF, retaining the output.
326		out2, late2, err2 := runScriptedPartitionedSliding(t, []scriptedStep{
327			stepData(throughFirstWatermark),
328			stepZeroReads(100),
329			stepData(unterminatedOther + "\n"),
330			stepZeroReads(100),
331		})
332		if err2 != nil {
333			t.Fatalf("terminated watermark then stall: unexpected error: %v", err2)
334		}
335		want := `{"key":"温度","start":0,"end":1000,"count":1,"sum":2}` + "\n"
336		if out2 != want {
337			t.Fatalf("min watermark after both partitions report:\n got: %q\nwant: %q", out2, want)
338		}
339		if late2 != "" {
340			t.Fatalf("unexpected late notices: %q", late2)
341		}
342	}
343	
344	// TestZeroByteReadFailureKeepsEmittedOutputAndStops covers the failure side:
345	// once io.ErrNoProgress fires, previously fully written windows and late
346	// notices stay, the still-open overlap window is not emitted, a newline-less tail
347	// that happens to be valid JSON never becomes a watermark, data the reader
348	// only provides afterwards produces nothing, and no further Read happens.
349	func TestZeroByteReadFailureKeepsEmittedOutputAndStops(t *testing.T) {
350		lines := stallScenarioLines()
351		throughLate := strings.Join(lines[:7], "\n") + "\n" // lines 1..7, late event closed
352		// Buffered tail at failure time: valid JSON watermark WITHOUT a newline.
353		// Were it processed it would close [600,1600); it must be ignored.
354		tail := lines[7]
355		// Data only "provided later": a complete terminating newline that would
356		// finish the tail, a further watermark and an event -- none may be read.
357		after := "\n" +
358			`{"type":"watermark","time":2600,"partition":0}` + "\n" +
359			`{"type":"event","key":"温度","time":2100,"value":4,"partition":0}` + "\n"
360	
361		wantOut := `{"key":"温度","start":0,"end":1000,"count":1,"sum":2}` + "\n"
362	
363		out, late, err := runScriptedPartitionedSliding(t, []scriptedStep{
364			stepData(throughLate),
365			stepZeroReads(50),
366			stepData(tail[:10]), // a few watermark bytes reset the count once...
367			stepZeroReads(60),
368			stepData(tail[10:]), // ...rest of the valid JSON, still newline-less
369			stepZeroReads(101),  // consecutive no-progress limit
370			stepData(after),     // must never be handed to the aggregator
371			stepPoison(errSentinelChunkedRead),
372		})
373		if !errors.Is(err, io.ErrNoProgress) {
374			t.Fatalf("error = %v, want io.ErrNoProgress", err)
375		}
376		if err != io.ErrNoProgress {
377			t.Fatalf("error must be the bare sentinel, got %T: %v", err, err)
378		}
379		if errors.Is(err, errSentinelChunkedRead) {
380			t.Fatalf("the run must stop reading at the limit; the poison read was reached")
381		}
382		if _, ok := err.(*InputError); ok {
383			t.Fatalf("a progress failure must not surface as an input-line parse error: %v", err)
384		}
385		if out != wantOut {
386			t.Fatalf("emitted window retained; open overlap window and post-failure data must add nothing:\n got: %q\nwant: %q", out, wantOut)
387		}
388		if late != stallScenarioLate {
389			t.Fatalf("late notice written before the failure must be retained:\n got: %q\nwant: %q", late, stallScenarioLate)
390		}
391	}
392	
393	// TestZeroByteReadCounterNotCumulativeAcrossRun covers two separate runs of
394	// exactly 100 zero-byte reads with only a few record bytes between them: the
395	// run later continues to a clean EOF with the full canonical result. The limit
396	// is consecutive, so 200 zero-byte reads spread across the run must not
397	// accumulate into a failure, even though a single run of 101 would.
398	func TestZeroByteReadCounterNotCumulativeAcrossRun(t *testing.T) {
399		input := canonicalChunkedScenario()
400		firstLineEnd := strings.IndexByte(input, '\n') + 1
401		secondLinePrefix := 4 // bytes `{"ty` of the second record
402	
403		var steps []scriptedStep
404		steps = append(steps,
405			stepData(input[:firstLineEnd]),
406			stepZeroReads(100),
407			stepData(input[firstLineEnd:firstLineEnd+secondLinePrefix]),
408			stepZeroReads(100),
409		)
410		// The remainder arrives in small pieces with short stalls, ending at EOF.
411		rest := input[firstLineEnd+secondLinePrefix:]
412		steps = append(steps, fragmentedSteps(rest, 5, 13)...)
413	
414		out, late, err := runScriptedPartitionedSliding(t, steps)
415		if err != nil {
416			t.Fatalf("two 100-stalls separated by record bytes must not accumulate: %v", err)
417		}
418		if out != canonicalChunkedWindows {
419			t.Fatalf("window output:\n got: %q\nwant: %q", out, canonicalChunkedWindows)
420		}
421		if late != canonicalChunkedLate {
422			t.Fatalf("late notice:\n got: %q\nwant: %q", late, canonicalChunkedLate)
423		}
424	}
425	
426	// TestZeroByteReadBlankLinesCountButStallsDoNot focuses on physical line
427	// numbering in legacy single-watermark mode: a blank line moves the counter,
428	// arbitrarily many zero-byte reads do not, and the late notice keeps the
429	// accurate physical number.
430	func TestZeroByteReadBlankLinesCountButStallsDoNot(t *testing.T) {
431		wm := `{"type":"watermark","time":500}`
432		ev := `{"type":"event","key":"k","time":100,"value":2}`
433	
434		var steps []scriptedStep
435		steps = append(steps, stepZeroReads(37)) // stalls before any byte: no line 1
436		steps = append(steps, stepData("\n"))    // physical line 1: blank
437		steps = append(steps, stepZeroReads(53))
438		steps = append(steps, fragmentedSteps(wm+"\n", 4, 11)...) // line 2
439		steps = append(steps, stepZeroReads(88))
440		steps = append(steps, stepData(ev+"\n"))  // line 3: late
441		steps = append(steps, stepZeroReads(100)) // tolerated; next Read is clean EOF
442	
443		var out, late bytes.Buffer
444		err := RunAggregate(&scriptedReader{steps: steps}, 1000, &out, &late)
445		if err != nil {
446			t.Fatalf("unexpected error: %v", err)
447		}
448		if out.String() != "" {
449			t.Fatalf("watermark 500 closes no window, got %q", out.String())
450		}
451		wantLate := "line 3: late event time=100 below current watermark 500, skipped\n"
452		if late.String() != wantLate {
453			t.Fatalf("late notice line number (blank line counts, 278 zero-byte reads do not):\n got: %q\nwant: %q", late.String(), wantLate)
454		}
455	}
456	
457	// TestZeroByteReadFailureAcrossEntryPoints makes sure the legacy fixed-window
458	// and sliding-only entries surface the same bare sentinel with the same
459	// retention rules, since every entry funnels through the same reader.
460	func TestZeroByteReadFailureAcrossEntryPoints(t *testing.T) {
461		events := strings.Join([]string{
462			`{"type":"event","key":"k","time":100,"value":2}`,
463			`{"type":"watermark","time":1000}`, // [0,1000) fully emitted
464			``,
465		}, "\n")
466		tail := `{"type":"watermark","time":2000}` // valid JSON, no newline
467	
468		entries := []struct {
469			name string
470			run  func(io.Reader, io.Writer, io.Writer) error
471		}{
472			{"fixed", func(r io.Reader, o, l io.Writer) error { return RunAggregate(r, 1000, o, l) }},
473			{"sliding", func(r io.Reader, o, l io.Writer) error { return RunAggregateSliding(r, 1000, 600, o, l) }},
474			{"partitioned", func(r io.Reader, o, l io.Writer) error {
475				return RunAggregatePartitionedSliding(r, 1000, 1000, 2, o, l)
476			}},
477		}
478		for _, fx := range entries {
479			fx := fx
480			t.Run(fx.name, func(t *testing.T) {
481				var steps []scriptedStep
482				if fx.name == "partitioned" {
483					events = strings.Join([]string{
484						`{"type":"event","key":"k","time":100,"value":2,"partition":0}`,
485						`{"type":"watermark","time":1000,"partition":0}`,
486						`{"type":"idle","partition":1}`, // lets the effective watermark become 1000
487						``,
488					}, "\n")
489					tail = `{"type":"watermark","time":2000,"partition":0}`
490				}
491				steps = []scriptedStep{
492					stepData(events),
493					stepZeroReads(101),
494					stepData(tail + "\n"), // would close/open more; must never be read
495					stepPoison(errSentinelChunkedRead),
496				}
497				var out, late bytes.Buffer
498				err := fx.run(&scriptedReader{steps: steps}, &out, &late)
499				if !errors.Is(err, io.ErrNoProgress) {
500					t.Fatalf("error = %v, want io.ErrNoProgress", err)
501				}
502				if errors.Is(err, errSentinelChunkedRead) {
503					t.Fatalf("reading must stop at the progress limit")
504				}
505				if _, ok := err.(*InputError); ok {
506					t.Fatalf("progress failure must not become an input error: %v", err)
507				}
508				want := `{"key":"k","start":0,"end":1000,"count":1,"sum":2}` + "\n"
509				if out.String() != want {
510					t.Fatalf("already emitted window stays, nothing else:\n got: %q\nwant: %q", out.String(), want)
511				}
512				if late.String() != "" {
513					t.Fatalf("no late events in this stream, got %q", late.String())
514				}
515			})
